mapper.select:
SELECT s.id AS seatId, s.area_id AS areaId, a.name AS areaName, s.seat_no AS seatNo, s.seat_type AS seatType, s.status AS status, u.real_name AS occupantName, s.assign_time AS assignTime FROM seat_info s LEFT JOIN seat_area a ON s.area_id = a.id LEFT JOIN sys_user u ON s.user_id = u.id WHERE s.deleted = 0 AND a.deleted = 0 AND u.deleted = 0
AND s.area_id = #{areaId}
AND s.seat_type = #{seatType}
AND s.status = #{status}
AND s.seat_no LIKE CONCAT('%', #{keyword}, '%')
ORDER BY s.area_id ASC, s.seat_no ASC
